window.REINO_COURSE = {"id": "reino02-ges-00002", "title": "Assistente de Logística", "category": "Gestão de Negócios", "area": "Logística e Operações", "code": "CURSO/GES/02/REINO02/00002", "hours": 40, "passScore": 7, "finalCount": 50, "modules": [{"id": 1, "title": "Fundamentos e documentação logística", "objective": "Mapear o fluxo logístico e registrar pedidos e documentos com organização.", "hours": 8, "lessons": [{"id": "log-m1-l1", "title": "Cadeia logística e papel do assistente", "text": "A logística coordena materiais, informações e atendimento desde o fornecedor até o cliente. O assistente registra movimentações, acompanha prazos e comunica ocorrências, respeitando a autorização de cada responsável. Uma entrega rápida com item errado continua sendo uma falha. O trabalho depende da integração entre compras, estoque, vendas e transporte. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Uma loja recebe 30 pedidos e precisa verificar disponibilidade, separar os itens, expedir e confirmar a entrega.", "task": "Desenhe o fluxo de um pedido e indique o registro e o responsável de cada etapa."}, {"id": "log-m1-l2", "title": "Fluxo físico e fluxo de informação", "text": "Fluxo físico é a movimentação dos produtos. Fluxo de informação acompanha pedido, quantidade, lote, localização, prazo e situação. Os dois precisam concordar. Registrar depois, de memória, aumenta a chance de diferenças. Uma movimentação deve ter origem, destino e responsável identificados. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Um item saiu da posição A01 para B03. O sistema precisa refletir a transferência, mesmo sem venda.", "task": "Crie uma ficha com data, item, quantidade, origem, destino e responsável."}, {"id": "log-m1-l3", "title": "Pedido, prazo e nível de serviço", "text": "O pedido precisa identificar cliente, itens, quantidade, endereço e prazo combinado. Nível de serviço mede o atendimento aos critérios definidos, não apenas velocidade. Antes de confirmar um prazo, verifique disponibilidade, capacidade de separação e transporte. Atualize o cliente quando uma ocorrência exigir revisão da previsão. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Um pedido para sexta depende de item que só chega na quinta. A equipe confirma capacidade antes de prometer.", "task": "Monte um checklist para confirmar um pedido e registrar sua previsão."}, {"id": "log-m1-l4", "title": "Documentos e rastreabilidade", "text": "Pedido de compra, documento fiscal e registro de recebimento cumprem funções diferentes. A conferência compara documentos com a carga recebida. Rastreabilidade liga item, lote, origem e movimentações. O assistente registra divergências e encaminha correções ao responsável; não improvisa alterações em documentos fiscais. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "O pedido indica 20 caixas, o documento 20 e a entrega 18. A diferença precisa ser registrada.", "task": "Organize uma ficha para comparar pedido, documento e quantidade física."}, {"id": "log-m1-l5", "title": "Segurança e organização do trabalho", "text": "O assistente apoia rotinas seguras e segue procedimentos do local. Corredores, saídas e áreas de movimentação precisam permanecer livres. Cargas e embalagens exigem limites e cuidados definidos pelo fabricante e pela empresa. Operar equipamentos depende de autorização e capacitação específica; este curso introdutório não habilita para operar empilhadeira. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Uma caixa ocupa uma saída e outra apresenta embalagem rompida. A equipe sinaliza e comunica as ocorrências.", "task": "Faça um checklist de organização com cinco riscos e a ação de encaminhamento."}], "questions": [{"id": "LOG-M1-L1-E1", "prompt": "Qual é o foco da logística?", "options": ["Integrar materiais, informações e atendimento", "Somente aumentar o estoque", "Substituir o setor financeiro", "Apenas divulgar produtos"], "kind": "exercise"}, {"id": "LOG-M1-L1-E2", "prompt": "Qual é uma atribuição do assistente?", "options": ["Registrar e comunicar ocorrências", "Prometer prazos sem verificar", "Alterar notas fiscais livremente", "Autorizar qualquer compra sem limite"], "kind": "exercise"}, {"id": "LOG-M1-L1-E3", "prompt": "Uma entrega rápida com produto errado representa:", "options": ["Falha na qualidade do atendimento", "Inventário concluído", "Redução garantida de custos", "Sucesso completo"], "kind": "exercise"}, {"id": "LOG-M1-L1-E4", "prompt": "Qual integração ajuda a cumprir um pedido?", "options": ["Somente publicidade", "Compras, estoque, vendas e transporte", "Somente limpeza", "Apenas a diretoria"], "kind": "exercise"}, {"id": "LOG-M1-L2-E1", "prompt": "Uma transferência interna movimenta:", "options": ["Apenas dinheiro", "Produtos entre localizações", "Somente mensagens", "Apenas publicidade"], "kind": "exercise"}, {"id": "LOG-M1-L2-E2", "prompt": "O fluxo de informação deve registrar:", "options": ["Item, quantidade, origem e destino", "Apenas o nome do motorista", "Só o telefone da loja", "Somente a cor da embalagem"], "kind": "exercise"}, {"id": "LOG-M1-L2-E3", "prompt": "Quando registrar uma movimentação?", "options": ["No momento previsto no procedimento", "Só no fim do mês", "Quando alguém lembrar", "Apenas no inventário anual"], "kind": "exercise"}, {"id": "LOG-M1-L2-E4", "prompt": "O que reduz divergências?", "options": ["Usar estimativas sem identificação", "Manter duas versões sem conferir", "Excluir transferências internas", "Conciliar movimento físico e registro"], "kind": "exercise"}, {"id": "LOG-M1-L3-E1", "prompt": "O que verificar antes de prometer prazo?", "options": ["A cor do produto", "A quantidade de seguidores", "Disponibilidade e capacidade de atendimento", "Somente a vontade do cliente"], "kind": "exercise"}, {"id": "LOG-M1-L3-E2", "prompt": "Nível de serviço depende de:", "options": ["Apenas estoque alto", "Somente velocidade", "Apenas preço baixo", "Critérios de atendimento definidos"], "kind": "exercise"}, {"id": "LOG-M1-L3-E3", "prompt": "Um pedido completo deve informar:", "options": ["Itens, quantidades, destino e prazo", "Apenas a forma de pagamento", "Só o valor do frete", "Somente o nome da loja"], "kind": "exercise"}, {"id": "LOG-M1-L3-E4", "prompt": "Se a previsão mudar, a equipe deve:", "options": ["Ocultar o atraso", "Confirmar uma data sem consultar", "Apagar o pedido", "Registrar e comunicar a nova situação"], "kind": "exercise"}, {"id": "LOG-M1-L4-E1", "prompt": "Na conferência, compara-se:", "options": ["Pedido, documento e carga física", "Apenas a embalagem externa", "Só o documento fiscal", "Somente o preço"], "kind": "exercise"}, {"id": "LOG-M1-L4-E2", "prompt": "Rastreabilidade relaciona:", "options": ["Apenas o valor total", "Item, lote, origem e movimentos", "Só a cor da caixa", "Somente o nome do cliente"], "kind": "exercise"}, {"id": "LOG-M1-L4-E3", "prompt": "Uma divergência documental deve ser:", "options": ["Corrigida por adivinhação", "Apagada sem autorização", "Registrada e encaminhada ao responsável", "Ignorada quando pequena"], "kind": "exercise"}, {"id": "LOG-M1-L4-E4", "prompt": "Pedido e documento fiscal são:", "options": ["Registros com funções diferentes", "Dispensáveis na conferência", "Sempre o mesmo arquivo", "Somente materiais de publicidade"], "kind": "exercise"}, {"id": "LOG-M1-L5-E1", "prompt": "Uma saída bloqueada deve ser:", "options": ["Mantida bloqueada até o inventário", "Usada como estoque extra", "Ignorada em dias calmos", "Liberada conforme procedimento seguro"], "kind": "exercise"}, {"id": "LOG-M1-L5-E2", "prompt": "Quem pode operar equipamento de movimentação?", "options": ["Qualquer pessoa disponível", "Qualquer aluno deste curso", "Todo visitante", "Pessoa autorizada e capacitada"], "kind": "exercise"}, {"id": "LOG-M1-L5-E3", "prompt": "Uma carga deve respeitar:", "options": ["Somente o peso estimado", "Apenas o espaço disponível", "Limites e condições definidos", "A altura que parecer melhor"], "kind": "exercise"}, {"id": "LOG-M1-L5-E4", "prompt": "Diante de risco, o assistente deve:", "options": ["Culpar alguém sem registro", "Improvisar sem avaliar", "Sinalizar e comunicar conforme o procedimento", "Esconder a ocorrência"], "kind": "exercise"}, {"id": "LOG-M1-L1-F1", "prompt": "Uma equipe está revisando sua rotina de cadeia logística e papel do assistente. Qual é o foco da logística?", "options": ["Apenas divulgar produtos", "Integrar materiais, informações e atendimento", "Somente aumentar o estoque", "Substituir o setor financeiro"], "kind": "final"}, {"id": "LOG-M1-L1-F2", "prompt": "Ao orientar um novo colega sobre cadeia logística e papel do assistente, o assistente precisa decidir com base no que aprendeu. Qual é uma atribuição do assistente?", "options": ["Autorizar qualquer compra sem limite", "Alterar notas fiscais livremente", "Prometer prazos sem verificar", "Registrar e comunicar ocorrências"], "kind": "final"}, {"id": "LOG-M1-L2-F1", "prompt": "Uma equipe está revisando sua rotina de fluxo físico e fluxo de informação. Uma transferência interna movimenta:", "options": ["Apenas publicidade", "Produtos entre localizações", "Somente mensagens", "Apenas dinheiro"], "kind": "final"}, {"id": "LOG-M1-L2-F2", "prompt": "Ao orientar um novo colega sobre fluxo físico e fluxo de informação, o assistente precisa decidir com base no que aprendeu. O fluxo de informação deve registrar:", "options": ["Só o telefone da loja", "Item, quantidade, origem e destino", "Somente a cor da embalagem", "Apenas o nome do motorista"], "kind": "final"}, {"id": "LOG-M1-L3-F1", "prompt": "Uma equipe está revisando sua rotina de pedido, prazo e nível de serviço. O que verificar antes de prometer prazo?", "options": ["A cor do produto", "Somente a vontade do cliente", "A quantidade de seguidores", "Disponibilidade e capacidade de atendimento"], "kind": "final"}, {"id": "LOG-M1-L3-F2", "prompt": "Ao orientar um novo colega sobre pedido, prazo e nível de serviço, o assistente precisa decidir com base no que aprendeu. Nível de serviço depende de:", "options": ["Apenas preço baixo", "Critérios de atendimento definidos", "Apenas estoque alto", "Somente velocidade"], "kind": "final"}, {"id": "LOG-M1-L4-F1", "prompt": "Uma equipe está revisando sua rotina de documentos e rastreabilidade. Na conferência, compara-se:", "options": ["Apenas a embalagem externa", "Somente o preço", "Só o documento fiscal", "Pedido, documento e carga física"], "kind": "final"}, {"id": "LOG-M1-L4-F2", "prompt": "Ao orientar um novo colega sobre documentos e rastreabilidade, o assistente precisa decidir com base no que aprendeu. Rastreabilidade relaciona:", "options": ["Somente o nome do cliente", "Só a cor da caixa", "Apenas o valor total", "Item, lote, origem e movimentos"], "kind": "final"}, {"id": "LOG-M1-L5-F1", "prompt": "Uma equipe está revisando sua rotina de segurança e organização do trabalho. Uma saída bloqueada deve ser:", "options": ["Usada como estoque extra", "Ignorada em dias calmos", "Liberada conforme procedimento seguro", "Mantida bloqueada até o inventário"], "kind": "final"}, {"id": "LOG-M1-L5-F2", "prompt": "Ao orientar um novo colega sobre segurança e organização do trabalho, o assistente precisa decidir com base no que aprendeu. Quem pode operar equipamento de movimentação?", "options": ["Todo visitante", "Qualquer aluno deste curso", "Pessoa autorizada e capacitada", "Qualquer pessoa disponível"], "kind": "final"}], "case": "Uma pequena distribuidora precisa melhorar a operação. Mapear o fluxo logístico e registrar pedidos e documentos com organização.", "practice": ["Desenhe o fluxo de um pedido e indique o registro e o responsável de cada etapa.", "Crie uma ficha com data, item, quantidade, origem, destino e responsável.", "Monte um checklist para confirmar um pedido e registrar sua previsão.", "Organize uma ficha para comparar pedido, documento e quantidade física.", "Faça um checklist de organização com cinco riscos e a ação de encaminhamento."], "studyPlan": {"explanations": 3, "examples": 1, "practice": 2, "review": 1, "questions": 1}, "visual": {"photo": "assets/logistica-visuals/capa-logistica.webp", "alt": "Operação de logística: equipe, mercadorias e registros", "caption": "Relacione a operação ilustrada com o esquema específico deste módulo.", "diagram": "assets/logistica-visuals/modulo1.svg", "diagramAlt": "Mapear o fluxo logístico e registrar pedidos e documentos com organização.", "kind": "Imagem ilustrativa; os esquemas apresentam o processo estudado."}}, {"id": 2, "title": "Recebimento e armazenagem", "objective": "Conferir recebimentos, tratar divergências e organizar a armazenagem.", "hours": 8, "lessons": [{"id": "log-m2-l1", "title": "Programação do recebimento", "text": "Programar recebimentos evita concentração de veículos e falta de espaço. Confira previsão, pedido, equipe e área disponível. Uma prioridade precisa ter motivo claro, como janela de entrega ou necessidade operacional. Agenda não substitui a conferência física. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Três fornecedores chegam no mesmo horário e há uma doca. A agenda distribui as janelas e informa responsáveis.", "task": "Proponha uma agenda de três recebimentos com horários e recursos."}, {"id": "log-m2-l2", "title": "Conferência quantitativa e qualitativa", "text": "Conferência quantitativa verifica quantidades e unidades. Conferência qualitativa verifica identificação, integridade, especificações e condições aplicáveis ao produto. Caixa, pacote e unidade não são sinônimos. Uma caixa com 12 unidades deve ser convertida corretamente quando o controle usa unidades. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Cinco caixas de 12 unidades representam 60 unidades. Se uma caixa tem 10, o recebido físico é 58.", "task": "Crie uma conferência com três itens, unidades e uma diferença física."}, {"id": "log-m2-l3", "title": "Avarias, divergências e quarentena", "text": "Uma avaria é um dano observado. Divergência é diferença entre o esperado e o conferido. Itens pendentes de avaliação devem ser identificados e segregados quando o procedimento exigir, sem misturar com estoque liberado. Registre evidências, quantidades e responsáveis antes de encaminhar uma decisão. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Duas embalagens estão rompidas. Elas ficam identificadas e separadas até a avaliação autorizada.", "task": "Redija um registro de ocorrência com fato, quantidade, evidência e encaminhamento."}, {"id": "log-m2-l4", "title": "Endereçamento e armazenagem", "text": "Endereçamento identifica corredor, estrutura, nível e posição conforme o padrão do depósito. Uma posição precisa ser legível e atualizada. Armazenagem considera acesso, características, compatibilidade e limites aplicáveis. Itens mais demandados podem ocupar posições acessíveis, sem comprometer segurança. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "O endereço C02-E03-N01-P04 permite localizar o item pela sequência do padrão adotado.", "task": "Desenhe seis posições e uma regra de identificação para um depósito fictício."}, {"id": "log-m2-l5", "title": "PEPS, FEFO e conservação", "text": "PEPS prioriza a saída dos itens que entraram primeiro. FEFO prioriza os que vencem primeiro. Validade pode ter prioridade maior que a ordem de entrada. A aplicação depende do produto e do procedimento. Observe condições de conservação e registros necessários, sem presumir uma temperatura universal. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "O lote A entrou antes, mas vence em dezembro; o B entrou depois e vence em novembro. Pelo FEFO, B sai primeiro.", "task": "Ordene três lotes por entrada e validade; explique a diferença entre PEPS e FEFO."}], "questions": [{"id": "LOG-M2-L1-E1", "prompt": "Programar recebimentos ajuda a:", "options": ["Eliminar a conferência", "Dispensar documentos", "Receber tudo sem espaço", "Distribuir recursos e reduzir filas"], "kind": "exercise"}, {"id": "LOG-M2-L1-E2", "prompt": "Antes de agendar, confirme:", "options": ["Só o preço de venda", "Somente a marca do veículo", "Apenas o nome do vendedor", "Pedido, previsão, equipe e espaço"], "kind": "exercise"}, {"id": "LOG-M2-L1-E3", "prompt": "Uma prioridade deve ter:", "options": ["Critério e justificativa registrados", "Preferência pessoal apenas", "Ordem aleatória", "Ausência de responsável"], "kind": "exercise"}, {"id": "LOG-M2-L1-E4", "prompt": "A agenda substitui a conferência física?", "options": ["Somente em compras grandes", "Sim, sempre", "Sim, se o fornecedor for conhecido", "Não, são controles complementares"], "kind": "exercise"}, {"id": "LOG-M2-L2-E1", "prompt": "Cinco caixas de 12 unidades totalizam:", "options": ["5 unidades", "17 unidades", "60 unidades", "12 unidades"], "kind": "exercise"}, {"id": "LOG-M2-L2-E2", "prompt": "Conferência qualitativa avalia:", "options": ["Somente a quantidade", "Identificação, integridade e condições", "Apenas o número de caixas", "Só o endereço"], "kind": "exercise"}, {"id": "LOG-M2-L2-E3", "prompt": "Com quatro caixas de 12 e uma de 10, foram recebidas:", "options": ["60 unidades", "58 unidades", "22 unidades", "48 unidades"], "kind": "exercise"}, {"id": "LOG-M2-L2-E4", "prompt": "Unidade de medida deve ser:", "options": ["Escolhida depois do inventário", "Confirmada antes de lançar quantidades", "Ignorada na comparação", "Sempre considerada caixa"], "kind": "exercise"}, {"id": "LOG-M2-L3-E1", "prompt": "Um produto com dano observado apresenta:", "options": ["Reposição automática", "Avaria", "Inventário aprovado", "Venda concluída"], "kind": "exercise"}, {"id": "LOG-M2-L3-E2", "prompt": "O estoque em quarentena deve ficar:", "options": ["Sem etiqueta", "Identificado e separado do liberado", "Sempre enviado ao cliente", "Misturado aos itens disponíveis"], "kind": "exercise"}, {"id": "LOG-M2-L3-E3", "prompt": "O registro de ocorrência deve conter:", "options": ["Apenas uma acusação", "Somente opinião pessoal", "Uma previsão sem base", "Fatos, quantidade, evidências e encaminhamento"], "kind": "exercise"}, {"id": "LOG-M2-L3-E4", "prompt": "Quem define a liberação do item pendente?", "options": ["Responsável autorizado pelo procedimento", "A pessoa que quiser liberar espaço", "Qualquer visitante", "O cliente sem inspeção"], "kind": "exercise"}, {"id": "LOG-M2-L4-E1", "prompt": "O endereçamento serve para:", "options": ["Definir publicidade", "Localizar itens de forma padronizada", "Eliminar o cadastro do item", "Calcular impostos automaticamente"], "kind": "exercise"}, {"id": "LOG-M2-L4-E2", "prompt": "Uma mudança de posição exige:", "options": ["Apagar o histórico", "Somente mover fisicamente", "Trocar o nome do produto", "Atualização do registro de localização"], "kind": "exercise"}, {"id": "LOG-M2-L4-E3", "prompt": "A posição de armazenagem depende de:", "options": ["Apenas espaço vazio", "Cor da caixa apenas", "Características, acesso e limites", "Somente preferência pessoal"], "kind": "exercise"}, {"id": "LOG-M2-L4-E4", "prompt": "Itens de maior demanda podem ficar:", "options": ["Sem qualquer identificação", "Em locais acessíveis e seguros", "Sempre no nível mais alto", "Sempre em saídas de emergência"], "kind": "exercise"}, {"id": "LOG-M2-L5-E1", "prompt": "PEPS prioriza:", "options": ["Maior embalagem", "Maior preço", "Última compra", "Primeira entrada"], "kind": "exercise"}, {"id": "LOG-M2-L5-E2", "prompt": "FEFO prioriza:", "options": ["Última entrada", "Menor custo", "Maior quantidade", "Menor prazo de validade"], "kind": "exercise"}, {"id": "LOG-M2-L5-E3", "prompt": "No exemplo, pelo FEFO, qual lote sai primeiro?", "options": ["Nenhum pode sair", "A, que entrou antes", "B, que vence em novembro", "Os dois sempre juntos"], "kind": "exercise"}, {"id": "LOG-M2-L5-E4", "prompt": "Condições de conservação devem seguir:", "options": ["A preferência do conferente", "Requisitos do produto e procedimento", "Uma temperatura igual para tudo", "Somente o clima do dia"], "kind": "exercise"}, {"id": "LOG-M2-L1-F1", "prompt": "Uma equipe está revisando sua rotina de programação do recebimento. Programar recebimentos ajuda a:", "options": ["Eliminar a conferência", "Receber tudo sem espaço", "Dispensar documentos", "Distribuir recursos e reduzir filas"], "kind": "final"}, {"id": "LOG-M2-L1-F2", "prompt": "Ao orientar um novo colega sobre programação do recebimento, o assistente precisa decidir com base no que aprendeu. Antes de agendar, confirme:", "options": ["Pedido, previsão, equipe e espaço", "Só o preço de venda", "Somente a marca do veículo", "Apenas o nome do vendedor"], "kind": "final"}, {"id": "LOG-M2-L2-F1", "prompt": "Uma equipe está revisando sua rotina de conferência quantitativa e qualitativa. Cinco caixas de 12 unidades totalizam:", "options": ["17 unidades", "5 unidades", "60 unidades", "12 unidades"], "kind": "final"}, {"id": "LOG-M2-L2-F2", "prompt": "Ao orientar um novo colega sobre conferência quantitativa e qualitativa, o assistente precisa decidir com base no que aprendeu. Conferência qualitativa avalia:", "options": ["Só o endereço", "Apenas o número de caixas", "Identificação, integridade e condições", "Somente a quantidade"], "kind": "final"}, {"id": "LOG-M2-L3-F1", "prompt": "Uma equipe está revisando sua rotina de avarias, divergências e quarentena. Um produto com dano observado apresenta:", "options": ["Inventário aprovado", "Reposição automática", "Venda concluída", "Avaria"], "kind": "final"}, {"id": "LOG-M2-L3-F2", "prompt": "Ao orientar um novo colega sobre avarias, divergências e quarentena, o assistente precisa decidir com base no que aprendeu. O estoque em quarentena deve ficar:", "options": ["Sempre enviado ao cliente", "Identificado e separado do liberado", "Sem etiqueta", "Misturado aos itens disponíveis"], "kind": "final"}, {"id": "LOG-M2-L4-F1", "prompt": "Uma equipe está revisando sua rotina de endereçamento e armazenagem. O endereçamento serve para:", "options": ["Localizar itens de forma padronizada", "Calcular impostos automaticamente", "Eliminar o cadastro do item", "Definir publicidade"], "kind": "final"}, {"id": "LOG-M2-L4-F2", "prompt": "Ao orientar um novo colega sobre endereçamento e armazenagem, o assistente precisa decidir com base no que aprendeu. Uma mudança de posição exige:", "options": ["Somente mover fisicamente", "Trocar o nome do produto", "Apagar o histórico", "Atualização do registro de localização"], "kind": "final"}, {"id": "LOG-M2-L5-F1", "prompt": "Uma equipe está revisando sua rotina de peps, fefo e conservação. PEPS prioriza:", "options": ["Maior preço", "Primeira entrada", "Última compra", "Maior embalagem"], "kind": "final"}, {"id": "LOG-M2-L5-F2", "prompt": "Ao orientar um novo colega sobre peps, fefo e conservação, o assistente precisa decidir com base no que aprendeu. FEFO prioriza:", "options": ["Maior quantidade", "Última entrada", "Menor prazo de validade", "Menor custo"], "kind": "final"}], "case": "Uma pequena distribuidora precisa melhorar a operação. Conferir recebimentos, tratar divergências e organizar a armazenagem.", "practice": ["Proponha uma agenda de três recebimentos com horários e recursos.", "Crie uma conferência com três itens, unidades e uma diferença física.", "Redija um registro de ocorrência com fato, quantidade, evidência e encaminhamento.", "Desenhe seis posições e uma regra de identificação para um depósito fictício.", "Ordene três lotes por entrada e validade; explique a diferença entre PEPS e FEFO."], "studyPlan": {"explanations": 3, "examples": 1, "practice": 2, "review": 1, "questions": 1}, "visual": {"photo": "assets/logistica-visuals/capa-logistica.webp", "alt": "Operação de logística: equipe, mercadorias e registros", "caption": "Relacione a operação ilustrada com o esquema específico deste módulo.", "diagram": "assets/logistica-visuals/modulo2.svg", "diagramAlt": "Conferir recebimentos, tratar divergências e organizar a armazenagem.", "kind": "Imagem ilustrativa; os esquemas apresentam o processo estudado."}}, {"id": 3, "title": "Estoque, inventário e ferramentas digitais", "objective": "Controlar movimentações, contar estoque e apoiar decisões de reposição.", "hours": 8, "lessons": [{"id": "log-m3-l1", "title": "Cadastro e movimentações de estoque", "text": "Cadastro identifica o item, unidade de controle e características necessárias. Cada entrada, saída e transferência deve corresponder a uma operação real. O saldo deriva do saldo inicial mais entradas menos saídas, observando ajustes autorizados. Duplicidade de lançamento distorce a disponibilidade. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Saldo inicial 40, entrada 15 e saída 12 resultam em 43 unidades.", "task": "Monte uma ficha com cinco movimentos e confira o saldo após cada um."}, {"id": "log-m3-l2", "title": "Inventário e tratamento de diferenças", "text": "Inventário compara quantidade física e saldo registrado em uma data definida. Planeje escopo, responsáveis e tratamento das movimentações durante a contagem. Diferenças precisam de recontagem e investigação antes de ajuste autorizado. Uma contagem sem unidade e localização não permite comparação confiável. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "O sistema mostra 80 e a contagem 76. A equipe reconta e verifica saídas pendentes antes de ajustar.", "task": "Prepare um inventário de cinco itens com saldo, contagem, diferença e ação."}, {"id": "log-m3-l3", "title": "Classificação ABC", "text": "A classificação ABC pode priorizar itens pelo valor anual de consumo, obtido multiplicando quantidade consumida pelo custo unitário. A empresa define os limites de cada classe. Classe A não significa necessariamente maior quantidade física. Criticidade, validade e risco podem exigir controles adicionais. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Item X: 100 unidades a R$50 = R$5.000; Y: 500 a R$2 = R$1.000. X tem maior valor de consumo.", "task": "Compare quatro itens por consumo e custo; proponha prioridades de acompanhamento."}, {"id": "log-m3-l4", "title": "Reposição e ponto de pedido", "text": "O ponto de pedido sinaliza quando repor, considerando demanda durante o prazo de reposição e estoque de segurança. Em um modelo simples, demanda média diária vezes prazo em dias mais segurança forma o ponto de pedido. É uma estimativa que precisa de dados consistentes e revisão. Pedido em aberto e reservas também influenciam a decisão. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Demanda 10/dia, reposição 4 dias e segurança 15: ponto de pedido = 55 unidades.", "task": "Calcule dois pontos de pedido e explique como uma mudança no prazo altera a necessidade."}, {"id": "log-m3-l5", "title": "Planilhas, WMS e qualidade dos dados", "text": "Planilha organiza controles simples; WMS apoia a gestão de operações de armazenagem. Ferramentas não substituem o registro correto. Use campos definidos, validação, responsáveis e acesso adequado. Integrações precisam ser conferidas. Alterações devem manter rastreabilidade, evitando várias versões contraditórias do mesmo controle. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Uma planilha aceita saída negativa e aumenta o saldo indevidamente. Uma validação ajuda a detectar a inconsistência.", "task": "Crie colunas e três regras de validação para uma ficha de estoque."}], "questions": [{"id": "LOG-M3-L1-E1", "prompt": "Com saldo 40, entrada 15 e saída 12, o final é:", "options": ["15", "43", "67", "37"], "kind": "exercise"}, {"id": "LOG-M3-L1-E2", "prompt": "O cadastro deve informar:", "options": ["Identificação e unidade de controle", "Apenas uma foto", "Somente preço de venda", "Só nome do motorista"], "kind": "exercise"}, {"id": "LOG-M3-L1-E3", "prompt": "Entrada lançada duas vezes pode:", "options": ["Eliminar perdas reais", "Aumentar indevidamente o saldo registrado", "Melhorar a precisão", "Confirmar o inventário"], "kind": "exercise"}, {"id": "LOG-M3-L1-E4", "prompt": "Uma transferência deve registrar:", "options": ["Somente a venda", "Apenas o preço", "Nenhum movimento", "Origem, destino e quantidade"], "kind": "exercise"}, {"id": "LOG-M3-L2-E1", "prompt": "O inventário compara:", "options": ["Frete e salário", "Venda e publicidade", "Preço e tamanho da loja", "Quantidade física e saldo registrado"], "kind": "exercise"}, {"id": "LOG-M3-L2-E2", "prompt": "Com saldo 80 e contagem 76, a diferença física menos sistema é:", "options": ["80", "-4", "4", "156"], "kind": "exercise"}, {"id": "LOG-M3-L2-E3", "prompt": "Antes de ajustar uma diferença, deve-se:", "options": ["Recontar e investigar os registros", "Modificar o pedido do cliente", "Ajustar sem autorização", "Apagar o saldo"], "kind": "exercise"}, {"id": "LOG-M3-L2-E4", "prompt": "Durante a contagem, movimentações precisam ser:", "options": ["Controladas conforme o plano", "Concluídas sem identificar horário", "Sempre feitas sem registro", "Ignoradas"], "kind": "exercise"}, {"id": "LOG-M3-L3-E1", "prompt": "Valor de consumo é calculado por:", "options": ["Preço mais peso", "Quantidade consumida vezes custo unitário", "Quantidade menos custo", "Frete dividido por validade"], "kind": "exercise"}, {"id": "LOG-M3-L3-E2", "prompt": "No exemplo, o maior valor de consumo é do:", "options": ["Nenhum item", "Item X", "Item Y", "Ambos iguais"], "kind": "exercise"}, {"id": "LOG-M3-L3-E3", "prompt": "Um item classe A é sempre o de maior quantidade?", "options": ["Sim, obrigatoriamente", "Somente se for importado", "Não, depende do critério de classificação", "Sempre o mais volumoso"], "kind": "exercise"}, {"id": "LOG-M3-L3-E4", "prompt": "Além de ABC, avalie:", "options": ["Apenas embalagem bonita", "Somente cor", "Número de fornecedores sem contexto", "Criticidade, validade e risco"], "kind": "exercise"}, {"id": "LOG-M3-L4-E1", "prompt": "No exemplo, o ponto de pedido é:", "options": ["29 unidades", "40 unidades", "150 unidades", "55 unidades"], "kind": "exercise"}, {"id": "LOG-M3-L4-E2", "prompt": "Se o prazo aumenta e a demanda permanece, a necessidade tende a:", "options": ["Diminuir sempre", "Desaparecer", "Aumentar", "Ficar sempre igual"], "kind": "exercise"}, {"id": "LOG-M3-L4-E3", "prompt": "O estoque de segurança busca:", "options": ["Amortecer incertezas definidas no planejamento", "Substituir toda compra", "Eliminar registros", "Garantir ausência total de risco"], "kind": "exercise"}, {"id": "LOG-M3-L4-E4", "prompt": "Antes de repor, também consulte:", "options": ["Só o número de clientes", "Reservas e pedidos em aberto", "Apenas o saldo de ontem", "Somente a cor do item"], "kind": "exercise"}, {"id": "LOG-M3-L5-E1", "prompt": "WMS apoia principalmente:", "options": ["Somente redes sociais", "Operações de armazenagem", "Apenas folha de pagamento", "Somente edição de vídeo"], "kind": "exercise"}, {"id": "LOG-M3-L5-E2", "prompt": "Uma validação de dados ajuda a:", "options": ["Garantir que toda entrada seja verdadeira", "Detectar lançamentos inconsistentes", "Substituir o responsável", "Eliminar a conferência física"], "kind": "exercise"}, {"id": "LOG-M3-L5-E3", "prompt": "Versões contraditórias exigem:", "options": ["Mais cópias sem identificação", "Exclusão de todo histórico", "Envio público de todos os dados", "Controle de versão e referência oficial"], "kind": "exercise"}, {"id": "LOG-M3-L5-E4", "prompt": "Integração de sistemas deve ser:", "options": ["Desligada sempre", "Conferida e acompanhada", "Usada para dispensar registros", "Aceita sem qualquer revisão"], "kind": "exercise"}, {"id": "LOG-M3-L1-F1", "prompt": "Uma equipe está revisando sua rotina de cadastro e movimentações de estoque. Com saldo 40, entrada 15 e saída 12, o final é:", "options": ["43", "67", "15", "37"], "kind": "final"}, {"id": "LOG-M3-L1-F2", "prompt": "Ao orientar um novo colega sobre cadastro e movimentações de estoque, o assistente precisa decidir com base no que aprendeu. O cadastro deve informar:", "options": ["Somente preço de venda", "Só nome do motorista", "Identificação e unidade de controle", "Apenas uma foto"], "kind": "final"}, {"id": "LOG-M3-L2-F1", "prompt": "Uma equipe está revisando sua rotina de inventário e tratamento de diferenças. O inventário compara:", "options": ["Preço e tamanho da loja", "Venda e publicidade", "Frete e salário", "Quantidade física e saldo registrado"], "kind": "final"}, {"id": "LOG-M3-L2-F2", "prompt": "Ao orientar um novo colega sobre inventário e tratamento de diferenças, o assistente precisa decidir com base no que aprendeu. Com saldo 80 e contagem 76, a diferença física menos sistema é:", "options": ["-4", "4", "80", "156"], "kind": "final"}, {"id": "LOG-M3-L3-F1", "prompt": "Uma equipe está revisando sua rotina de classificação abc. Valor de consumo é calculado por:", "options": ["Quantidade consumida vezes custo unitário", "Preço mais peso", "Frete dividido por validade", "Quantidade menos custo"], "kind": "final"}, {"id": "LOG-M3-L3-F2", "prompt": "Ao orientar um novo colega sobre classificação abc, o assistente precisa decidir com base no que aprendeu. No exemplo, o maior valor de consumo é do:", "options": ["Nenhum item", "Ambos iguais", "Item Y", "Item X"], "kind": "final"}, {"id": "LOG-M3-L4-F1", "prompt": "Uma equipe está revisando sua rotina de reposição e ponto de pedido. No exemplo, o ponto de pedido é:", "options": ["29 unidades", "40 unidades", "55 unidades", "150 unidades"], "kind": "final"}, {"id": "LOG-M3-L4-F2", "prompt": "Ao orientar um novo colega sobre reposição e ponto de pedido, o assistente precisa decidir com base no que aprendeu. Se o prazo aumenta e a demanda permanece, a necessidade tende a:", "options": ["Aumentar", "Diminuir sempre", "Ficar sempre igual", "Desaparecer"], "kind": "final"}, {"id": "LOG-M3-L5-F1", "prompt": "Uma equipe está revisando sua rotina de planilhas, wms e qualidade dos dados. WMS apoia principalmente:", "options": ["Apenas folha de pagamento", "Operações de armazenagem", "Somente redes sociais", "Somente edição de vídeo"], "kind": "final"}, {"id": "LOG-M3-L5-F2", "prompt": "Ao orientar um novo colega sobre planilhas, wms e qualidade dos dados, o assistente precisa decidir com base no que aprendeu. Uma validação de dados ajuda a:", "options": ["Eliminar a conferência física", "Garantir que toda entrada seja verdadeira", "Detectar lançamentos inconsistentes", "Substituir o responsável"], "kind": "final"}], "case": "Uma pequena distribuidora precisa melhorar a operação. Controlar movimentações, contar estoque e apoiar decisões de reposição.", "practice": ["Monte uma ficha com cinco movimentos e confira o saldo após cada um.", "Prepare um inventário de cinco itens com saldo, contagem, diferença e ação.", "Compare quatro itens por consumo e custo; proponha prioridades de acompanhamento.", "Calcule dois pontos de pedido e explique como uma mudança no prazo altera a necessidade.", "Crie colunas e três regras de validação para uma ficha de estoque."], "studyPlan": {"explanations": 3, "examples": 1, "practice": 2, "review": 1, "questions": 1}, "visual": {"photo": "assets/logistica-visuals/capa-logistica.webp", "alt": "Operação de logística: equipe, mercadorias e registros", "caption": "Relacione a operação ilustrada com o esquema específico deste módulo.", "diagram": "assets/logistica-visuals/modulo3.svg", "diagramAlt": "Controlar movimentações, contar estoque e apoiar decisões de reposição.", "kind": "Imagem ilustrativa; os esquemas apresentam o processo estudado."}}, {"id": 4, "title": "Separação, expedição e transportes", "objective": "Separar pedidos, conferir volumes e acompanhar transporte e expedição.", "hours": 7, "lessons": [{"id": "log-m4-l1", "title": "Separação e conferência de pedidos", "text": "Separação, ou picking, coleta itens conforme o pedido. Confirme código, quantidade, unidade e critérios como lote ou validade. A conferência antes da expedição reduz trocas. Reservar estoque não equivale a expedir. Uma falta identificada precisa ser registrada e encaminhada antes de prometer entrega completa. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "O pedido pede 3 unidades de SKU100; SKU101 é parecido, mas não pode ser enviado como substituto sem autorização.", "task": "Monte um checklist de separação para três itens semelhantes."}, {"id": "log-m4-l2", "title": "Embalagem e identificação", "text": "A embalagem protege o item e precisa ser compatível com suas características e o trajeto. Identificação relaciona volume, pedido e destino. Confira legibilidade e requisitos aplicáveis, sem expor dados pessoais além do necessário. Consolidar volumes exige evitar mistura entre pedidos. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Dois pedidos usam caixas iguais. Etiquetas com identificador do pedido e número do volume evitam troca.", "task": "Proponha uma etiqueta e um checklist de embalagem para dois pedidos."}, {"id": "log-m4-l3", "title": "Expedição e comprovantes", "text": "Expedição verifica pedidos, volumes, destino, documentos e condições de saída. Registre quem recebeu a carga, horário e ocorrências pertinentes. Comprovante de coleta não é automaticamente comprovante de entrega ao cliente. A atualização do status precisa refletir a etapa realmente concluída. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Uma transportadora coletou quatro volumes. O pedido fica coletado, não entregue ao destinatário.", "task": "Crie registros distintos para coleta e entrega de um pedido."}, {"id": "log-m4-l4", "title": "Transportes e escolha operacional", "text": "A escolha operacional compara prazo, custo total, capacidade, cobertura e requisitos do produto. Um frete menor pode gerar custo maior se causar avarias ou descumprir prazos. O assistente reúne dados e acompanha a execução; decisões e requisitos especializados seguem responsáveis autorizados. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Opção A custa R$80 e atende o prazo; B custa R$60, mas chega depois da data combinada. Preço isolado não resolve a escolha.", "task": "Compare duas opções fictícias por prazo, custo e risco e justifique um encaminhamento."}, {"id": "log-m4-l5", "title": "Roteirização e acompanhamento", "text": "Roteirização organiza paradas considerando endereços, janelas, capacidade e restrições operacionais. A menor distância não garante a melhor rota se houver horários obrigatórios. Acompanhe eventos e revise a previsão com dados confirmados. Mudanças de rota precisam de comunicação e registro conforme o procedimento. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Cliente A recebe até 10h e B até 17h. A sequência considera as janelas, além da distância.", "task": "Planeje três paradas fictícias com janelas e uma ocorrência de atraso."}], "questions": [{"id": "LOG-M4-L1-E1", "prompt": "Picking é:", "options": ["Separação dos itens de um pedido", "Recebimento do frete", "Descarte de resíduos", "Apenas emissão de boleto"], "kind": "exercise"}, {"id": "LOG-M4-L1-E2", "prompt": "Itens visualmente parecidos exigem conferir:", "options": ["Apenas o tamanho da caixa", "Somente a cor", "Código e especificação", "Só a posição na prateleira"], "kind": "exercise"}, {"id": "LOG-M4-L1-E3", "prompt": "Uma reserva significa que o item já foi expedido?", "options": ["Somente se for caro", "Sim, sempre", "Não, são etapas distintas", "Sempre que existe pedido"], "kind": "exercise"}, {"id": "LOG-M4-L1-E4", "prompt": "Uma falta na separação deve ser:", "options": ["Registrada e encaminhada", "Lançada como entrega completa", "Substituída sem autorização", "Ocultada até a entrega"], "kind": "exercise"}, {"id": "LOG-M4-L2-E1", "prompt": "A embalagem deve considerar:", "options": ["Produto e condições do trajeto", "Cor da transportadora", "Apenas menor preço", "Somente aparência"], "kind": "exercise"}, {"id": "LOG-M4-L2-E2", "prompt": "Uma etiqueta precisa permitir:", "options": ["Eliminar a conferência", "Dispensar o registro de expedição", "Relacionar volume, pedido e destino", "Divulgar todos os dados pessoais"], "kind": "exercise"}, {"id": "LOG-M4-L2-E3", "prompt": "Dados pessoais devem ser:", "options": ["Publicados integralmente", "Limitados à finalidade da operação", "Usados sem controle", "Enviados a qualquer grupo"], "kind": "exercise"}, {"id": "LOG-M4-L2-E4", "prompt": "Ao consolidar volumes, evite:", "options": ["Identificação legível", "Registro por volume", "Mistura entre pedidos", "Conferência de destino"], "kind": "exercise"}, {"id": "LOG-M4-L3-E1", "prompt": "Antes da saída, confira:", "options": ["Só o número do cliente", "Somente a placa", "Apenas o prazo", "Pedido, volumes, destino e documentos"], "kind": "exercise"}, {"id": "LOG-M4-L3-E2", "prompt": "Coleta pela transportadora significa:", "options": ["Carga coletada, ainda a entregar", "Inventário encerrado", "Cliente recebeu tudo", "Pagamento confirmado"], "kind": "exercise"}, {"id": "LOG-M4-L3-E3", "prompt": "O status deve representar:", "options": ["O desejo da equipe", "A etapa realmente concluída", "A previsão mais otimista", "Sempre entrega final"], "kind": "exercise"}, {"id": "LOG-M4-L3-E4", "prompt": "O registro de saída deve identificar:", "options": ["Somente o nome da loja", "Apenas opinião", "Responsável, horário e ocorrência pertinente", "Só o valor de venda"], "kind": "exercise"}, {"id": "LOG-M4-L4-E1", "prompt": "Para comparar transportes, avalie:", "options": ["Somente menor frete", "Prazo, custo total, capacidade e requisitos", "Só o nome da empresa", "Apenas cor do veículo"], "kind": "exercise"}, {"id": "LOG-M4-L4-E2", "prompt": "Frete mais barato é sempre a melhor opção?", "options": ["Sim, sem exceção", "Sempre que há desconto", "Não, depende do conjunto de critérios", "Só em qualquer pedido pequeno"], "kind": "exercise"}, {"id": "LOG-M4-L4-E3", "prompt": "O assistente contribui reunindo:", "options": ["Opiniões sem registro", "Promessas sem consulta", "Dados confiáveis para a decisão", "Regras fiscais improvisadas"], "kind": "exercise"}, {"id": "LOG-M4-L4-E4", "prompt": "No exemplo, a opção B exige avaliar:", "options": ["Descumprimento do prazo combinado", "Quantidade de fotos do veículo", "Número de funcionários", "Apenas diferença de cor"], "kind": "exercise"}, {"id": "LOG-M4-L5-E1", "prompt": "Roteirização considera:", "options": ["Apenas ordem alfabética", "Somente distância", "Só maior valor de venda", "Paradas, janelas, capacidade e restrições"], "kind": "exercise"}, {"id": "LOG-M4-L5-E2", "prompt": "Uma janela de entrega é:", "options": ["O tempo de emissão da nota", "Intervalo previsto para atendimento", "O número de volumes", "O vidro do veículo"], "kind": "exercise"}, {"id": "LOG-M4-L5-E3", "prompt": "Menor distância sempre garante melhor rota?", "options": ["Não, existem outras restrições", "Sempre sem exceção", "Sim, obrigatoriamente", "Somente se houver clientes"], "kind": "exercise"}, {"id": "LOG-M4-L5-E4", "prompt": "Ao revisar uma previsão, use:", "options": ["Silêncio até o fim", "Uma data escolhida ao acaso", "Dados confirmados e comunicação registrada", "Suposição sem contexto"], "kind": "exercise"}, {"id": "LOG-M4-L1-F1", "prompt": "Uma equipe está revisando sua rotina de separação e conferência de pedidos. Picking é:", "options": ["Separação dos itens de um pedido", "Descarte de resíduos", "Recebimento do frete", "Apenas emissão de boleto"], "kind": "final"}, {"id": "LOG-M4-L1-F2", "prompt": "Ao orientar um novo colega sobre separação e conferência de pedidos, o assistente precisa decidir com base no que aprendeu. Itens visualmente parecidos exigem conferir:", "options": ["Código e especificação", "Apenas o tamanho da caixa", "Somente a cor", "Só a posição na prateleira"], "kind": "final"}, {"id": "LOG-M4-L2-F1", "prompt": "Uma equipe está revisando sua rotina de embalagem e identificação. A embalagem deve considerar:", "options": ["Produto e condições do trajeto", "Cor da transportadora", "Apenas menor preço", "Somente aparência"], "kind": "final"}, {"id": "LOG-M4-L2-F2", "prompt": "Ao orientar um novo colega sobre embalagem e identificação, o assistente precisa decidir com base no que aprendeu. Uma etiqueta precisa permitir:", "options": ["Relacionar volume, pedido e destino", "Eliminar a conferência", "Dispensar o registro de expedição", "Divulgar todos os dados pessoais"], "kind": "final"}, {"id": "LOG-M4-L3-F1", "prompt": "Uma equipe está revisando sua rotina de expedição e comprovantes. Antes da saída, confira:", "options": ["Só o número do cliente", "Apenas o prazo", "Pedido, volumes, destino e documentos", "Somente a placa"], "kind": "final"}, {"id": "LOG-M4-L3-F2", "prompt": "Ao orientar um novo colega sobre expedição e comprovantes, o assistente precisa decidir com base no que aprendeu. Coleta pela transportadora significa:", "options": ["Cliente recebeu tudo", "Pagamento confirmado", "Carga coletada, ainda a entregar", "Inventário encerrado"], "kind": "final"}, {"id": "LOG-M4-L4-F1", "prompt": "Uma equipe está revisando sua rotina de transportes e escolha operacional. Para comparar transportes, avalie:", "options": ["Somente menor frete", "Só o nome da empresa", "Prazo, custo total, capacidade e requisitos", "Apenas cor do veículo"], "kind": "final"}, {"id": "LOG-M4-L4-F2", "prompt": "Ao orientar um novo colega sobre transportes e escolha operacional, o assistente precisa decidir com base no que aprendeu. Frete mais barato é sempre a melhor opção?", "options": ["Só em qualquer pedido pequeno", "Não, depende do conjunto de critérios", "Sim, sem exceção", "Sempre que há desconto"], "kind": "final"}, {"id": "LOG-M4-L5-F1", "prompt": "Uma equipe está revisando sua rotina de roteirização e acompanhamento. Roteirização considera:", "options": ["Somente distância", "Paradas, janelas, capacidade e restrições", "Só maior valor de venda", "Apenas ordem alfabética"], "kind": "final"}, {"id": "LOG-M4-L5-F2", "prompt": "Ao orientar um novo colega sobre roteirização e acompanhamento, o assistente precisa decidir com base no que aprendeu. Uma janela de entrega é:", "options": ["Intervalo previsto para atendimento", "O tempo de emissão da nota", "O vidro do veículo", "O número de volumes"], "kind": "final"}], "case": "Uma pequena distribuidora precisa melhorar a operação. Separar pedidos, conferir volumes e acompanhar transporte e expedição.", "practice": ["Monte um checklist de separação para três itens semelhantes.", "Proponha uma etiqueta e um checklist de embalagem para dois pedidos.", "Crie registros distintos para coleta e entrega de um pedido.", "Compare duas opções fictícias por prazo, custo e risco e justifique um encaminhamento.", "Planeje três paradas fictícias com janelas e uma ocorrência de atraso."], "studyPlan": {"explanations": 2.5, "examples": 0.5, "practice": 2, "review": 1, "questions": 1}, "visual": {"photo": "assets/logistica-visuals/capa-logistica.webp", "alt": "Operação de logística: equipe, mercadorias e registros", "caption": "Relacione a operação ilustrada com o esquema específico deste módulo.", "diagram": "assets/logistica-visuals/modulo4.svg", "diagramAlt": "Separar pedidos, conferir volumes e acompanhar transporte e expedição.", "kind": "Imagem ilustrativa; os esquemas apresentam o processo estudado."}}, {"id": 5, "title": "Entregas, retornos e melhoria contínua", "objective": "Acompanhar entregas, encaminhar retornos e avaliar indicadores de melhoria.", "hours": 7, "lessons": [{"id": "log-m5-l1", "title": "Devoluções e logística reversa", "text": "Devolução comercial e logística reversa ambiental têm finalidades relacionadas, mas não são sinônimos. A primeira pode tratar retorno por troca, erro ou defeito. A segunda organiza retorno e destinação adequada de produtos e resíduos nas cadeias aplicáveis. Recebimento, identificação e encaminhamento precisam seguir o procedimento adequado a cada caso. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Uma troca de tamanho retorna para avaliação comercial; uma pilha usada segue um sistema de destinação apropriado.", "task": "Compare dois fluxos de retorno e registre responsáveis e destino previsto."}, {"id": "log-m5-l2", "title": "Indicadores logísticos", "text": "Indicadores precisam de definição, período e fonte. Entregas no prazo divide entregas pontuais pelo total observado, conforme o critério adotado. Acuracidade pode ser medida por posições ou itens corretos sobre os verificados, definindo claramente a unidade. Uma porcentagem sem denominador dificulta interpretação. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "De 40 entregas, 36 pontuais: 36/40 vezes 100 = 90%.", "task": "Calcule dois indicadores e escreva período, numerador, denominador e fonte."}, {"id": "log-m5-l3", "title": "Ocorrências e melhoria contínua", "text": "Melhorar exige distinguir fato, hipótese e causa confirmada. Registre a ocorrência, investigue com evidências, proponha ação e confira o resultado. O ciclo PDCA organiza planejar, executar, verificar e agir. Não atribua toda diferença ao funcionário sem analisar processo, cadastro e integração. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Trocas frequentes ocorrem com códigos parecidos. A equipe testa uma segunda conferência e compara erros antes e depois.", "task": "Descreva um problema fictício e proponha um teste de melhoria com medida de resultado."}, {"id": "log-m5-l4", "title": "Custos e comunicação da operação", "text": "O custo logístico reúne componentes como armazenagem, separação, embalagem, transporte e retornos. A comparação precisa usar o mesmo período e escopo. Uma ocorrência comunicada deve informar pedido, fato, impacto, responsável e próxima ação. Custo menor em uma etapa pode aumentar perdas em outra. Registre os valores confirmados e indique o que ainda está pendente. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Uma expedição usa R$100 de transporte e R$20 de embalagem; o total destes dois componentes é R$120.", "task": "Monte um registro com três componentes de custo e uma mensagem de ocorrência ao responsável."}, {"id": "log-m5-l5", "title": "Projeto integrador de operação logística", "text": "O projeto integra pedido, recebimento, localização, estoque, separação, expedição e acompanhamento. Defina responsáveis e registros, confira saldos e trate ocorrências. A proposta deve equilibrar atendimento, confiabilidade e custo. Um relatório comunica resultado, pendência, ação e prazo, sem ocultar limitações dos dados. Faça os registros de modo legível, confira a unidade utilizada e comunique dúvidas antes de concluir a operação. As situações desta aula são didáticas e utilizam dados fictícios.", "example": "Uma loja recebe 50 unidades, separa 12 e entrega 10; duas permanecem pendentes. O relatório diferencia reserva, saída e entrega.", "task": "Monte um plano de uma página com fluxo, ficha de estoque, checklist de pedido, ocorrência e dois indicadores."}], "questions": [{"id": "LOG-M5-L1-E1", "prompt": "Devolução comercial e logística reversa ambiental são:", "options": ["Processos com finalidades distintas", "Sempre exatamente a mesma coisa", "Apenas transporte de ida", "Sinônimos de venda"], "kind": "exercise"}, {"id": "LOG-M5-L1-E2", "prompt": "Uma pilha usada deve seguir:", "options": ["Destinação apropriada à cadeia aplicável", "Estoque de produto novo", "Mistura automática com qualquer lixo", "Envio ao cliente seguinte"], "kind": "exercise"}, {"id": "LOG-M5-L1-E3", "prompt": "Um retorno precisa de:", "options": ["Liberação imediata para venda", "Somente uma caixa sem etiqueta", "Identificação, motivo e encaminhamento", "Ausência de registro"], "kind": "exercise"}, {"id": "LOG-M5-L1-E4", "prompt": "Uma troca por tamanho costuma ser:", "options": ["Nova fabricação", "Recebimento de fornecedor obrigatório", "Retorno comercial para avaliação", "Sempre resíduo perigoso"], "kind": "exercise"}, {"id": "LOG-M5-L2-E1", "prompt": "36 entregas pontuais de 40 correspondem a:", "options": ["90%", "10%", "36%", "40%"], "kind": "exercise"}, {"id": "LOG-M5-L2-E2", "prompt": "Um indicador deve informar:", "options": ["Apenas opinião", "Só nome do gestor", "Somente porcentagem", "Definição, período e fonte"], "kind": "exercise"}, {"id": "LOG-M5-L2-E3", "prompt": "Acuracidade de itens pode comparar:", "options": ["Rotas e salários", "Peso e divulgação", "Frete e faturamento", "Itens corretos e itens verificados"], "kind": "exercise"}, {"id": "LOG-M5-L2-E4", "prompt": "Uma porcentagem precisa de:", "options": ["Apenas um número atraente", "Somente o mês", "Nenhuma base de cálculo", "Numerador e denominador definidos"], "kind": "exercise"}, {"id": "LOG-M5-L3-E1", "prompt": "Uma causa deve ser confirmada com:", "options": ["Apenas impressão pessoal", "Acusação imediata", "Um boato", "Evidências e investigação"], "kind": "exercise"}, {"id": "LOG-M5-L3-E2", "prompt": "A sequência do PDCA é:", "options": ["Enviar, esconder, ajustar e culpar", "Vender, comprar, pagar e apagar", "Contar, imprimir, telefonar e sair", "Planejar, executar, verificar e agir"], "kind": "exercise"}, {"id": "LOG-M5-L3-E3", "prompt": "Após testar uma melhoria, deve-se:", "options": ["Eliminar todos os registros", "Declarar sucesso sem medir", "Parar qualquer conferência", "Comparar resultados conforme o indicador"], "kind": "exercise"}, {"id": "LOG-M5-L3-E4", "prompt": "Fato e hipótese devem ser:", "options": ["Distinguidos no registro", "Tratados sempre como certeza", "Substituídos por opinião", "Misturados sem identificação"], "kind": "exercise"}, {"id": "LOG-M5-L4-E1", "prompt": "Transporte de R$100 mais embalagem de R$20 somam:", "options": ["R$80", "R$2.000", "R$120", "R$100"], "kind": "exercise"}, {"id": "LOG-M5-L4-E2", "prompt": "Para comparar custos, mantenha:", "options": ["Período e escopo equivalentes", "Dados sem identificação", "Custos omitidos", "Somente o menor valor isolado"], "kind": "exercise"}, {"id": "LOG-M5-L4-E3", "prompt": "Uma comunicação de ocorrência deve trazer:", "options": ["Uma promessa sem consulta", "Pedido, fato, impacto e próxima ação", "Apenas um emoticon", "Só uma acusação"], "kind": "exercise"}, {"id": "LOG-M5-L4-E4", "prompt": "Um custo menor numa etapa pode:", "options": ["Eliminar retornos", "Garantir sempre economia total", "Aumentar perdas em outra etapa", "Dispensar a medição"], "kind": "exercise"}, {"id": "LOG-M5-L5-E1", "prompt": "Um projeto logístico deve integrar:", "options": ["Só a lista de clientes", "Somente a arte da capa", "Fluxo, responsáveis, registros e acompanhamento", "Apenas o preço do produto"], "kind": "exercise"}, {"id": "LOG-M5-L5-E2", "prompt": "Um relatório útil distingue:", "options": ["Suposições como fatos", "Somente elogios", "Resultado, pendência, ação e prazo", "Apenas desejos"], "kind": "exercise"}, {"id": "LOG-M5-L5-E3", "prompt": "Reservado, expedido e entregue são:", "options": ["Sempre o mesmo evento", "Apenas termos de marketing", "Situações diferentes do pedido", "Etapas dispensáveis"], "kind": "exercise"}, {"id": "LOG-M5-L5-E4", "prompt": "A decisão deve equilibrar:", "options": ["Apenas velocidade", "Estoque máximo sem análise", "Atendimento, confiabilidade e custo", "Só menor preço"], "kind": "exercise"}, {"id": "LOG-M5-L1-F1", "prompt": "Uma equipe está revisando sua rotina de devoluções e logística reversa. Devolução comercial e logística reversa ambiental são:", "options": ["Processos com finalidades distintas", "Sinônimos de venda", "Apenas transporte de ida", "Sempre exatamente a mesma coisa"], "kind": "final"}, {"id": "LOG-M5-L1-F2", "prompt": "Ao orientar um novo colega sobre devoluções e logística reversa, o assistente precisa decidir com base no que aprendeu. Uma pilha usada deve seguir:", "options": ["Estoque de produto novo", "Envio ao cliente seguinte", "Destinação apropriada à cadeia aplicável", "Mistura automática com qualquer lixo"], "kind": "final"}, {"id": "LOG-M5-L2-F1", "prompt": "Uma equipe está revisando sua rotina de indicadores logísticos. 36 entregas pontuais de 40 correspondem a:", "options": ["90%", "10%", "36%", "40%"], "kind": "final"}, {"id": "LOG-M5-L2-F2", "prompt": "Ao orientar um novo colega sobre indicadores logísticos, o assistente precisa decidir com base no que aprendeu. Um indicador deve informar:", "options": ["Somente porcentagem", "Só nome do gestor", "Apenas opinião", "Definição, período e fonte"], "kind": "final"}, {"id": "LOG-M5-L3-F1", "prompt": "Uma equipe está revisando sua rotina de ocorrências e melhoria contínua. Uma causa deve ser confirmada com:", "options": ["Apenas impressão pessoal", "Evidências e investigação", "Acusação imediata", "Um boato"], "kind": "final"}, {"id": "LOG-M5-L3-F2", "prompt": "Ao orientar um novo colega sobre ocorrências e melhoria contínua, o assistente precisa decidir com base no que aprendeu. A sequência do PDCA é:", "options": ["Vender, comprar, pagar e apagar", "Contar, imprimir, telefonar e sair", "Enviar, esconder, ajustar e culpar", "Planejar, executar, verificar e agir"], "kind": "final"}, {"id": "LOG-M5-L4-F1", "prompt": "Uma equipe está revisando sua rotina de custos e comunicação da operação. Transporte de R$100 mais embalagem de R$20 somam:", "options": ["R$120", "R$80", "R$2.000", "R$100"], "kind": "final"}, {"id": "LOG-M5-L4-F2", "prompt": "Ao orientar um novo colega sobre custos e comunicação da operação, o assistente precisa decidir com base no que aprendeu. Para comparar custos, mantenha:", "options": ["Período e escopo equivalentes", "Custos omitidos", "Dados sem identificação", "Somente o menor valor isolado"], "kind": "final"}, {"id": "LOG-M5-L5-F1", "prompt": "Uma equipe está revisando sua rotina de projeto integrador de operação logística. Um projeto logístico deve integrar:", "options": ["Só a lista de clientes", "Fluxo, responsáveis, registros e acompanhamento", "Apenas o preço do produto", "Somente a arte da capa"], "kind": "final"}, {"id": "LOG-M5-L5-F2", "prompt": "Ao orientar um novo colega sobre projeto integrador de operação logística, o assistente precisa decidir com base no que aprendeu. Um relatório útil distingue:", "options": ["Resultado, pendência, ação e prazo", "Somente elogios", "Suposições como fatos", "Apenas desejos"], "kind": "final"}], "case": "Uma pequena distribuidora precisa melhorar a operação. Acompanhar entregas, encaminhar retornos e avaliar indicadores de melhoria.", "practice": ["Compare dois fluxos de retorno e registre responsáveis e destino previsto.", "Calcule dois indicadores e escreva período, numerador, denominador e fonte.", "Descreva um problema fictício e proponha um teste de melhoria com medida de resultado.", "Monte um registro com três componentes de custo e uma mensagem de ocorrência ao responsável.", "Monte um plano de uma página com fluxo, ficha de estoque, checklist de pedido, ocorrência e dois indicadores."], "studyPlan": {"explanations": 2.5, "examples": 0.5, "practice": 2, "review": 1, "questions": 1}, "visual": {"photo": "assets/logistica-visuals/capa-logistica.webp", "alt": "Operação de logística: equipe, mercadorias e registros", "caption": "Relacione a operação ilustrada com o esquema específico deste módulo.", "diagram": "assets/logistica-visuals/modulo5.svg", "diagramAlt": "Acompanhar entregas, encaminhar retornos e avaliar indicadores de melhoria.", "kind": "Imagem ilustrativa; os esquemas apresentam o processo estudado."}}], "sources": [{"title": "Sebrae — Controle de estoque", "url": "https://meuatendimento.sebrae.com.br/sites/PortalSebrae/artigos/como-elaborar-o-controle-de-estoque-de-mercadorias,8e80438af1c92410VgnVCM100000b272010aRCRD"}, {"title": "SINIR — Logística reversa", "url": "https://www.sinir.gov.br/perfis/logistica-reversa/"}]};